// HasChannel applies the HasEdge predicate on the "channel" edge.
func HasChannel() predicate.UpstreamAccount {
	return predicate.UpstreamAccount(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ChannelTable, ChannelColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasChannelWith applies the HasEdge predicate on the "channel" edge with a given conditions (other predicates).
func HasChannelWith(preds ...predicate.Channel) predicate.UpstreamAccount {
	return predicate.UpstreamAccount(func(s *sql.Selector) {
		step := newChannelStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasPool applies the HasEdge predicate on the "pool" edge.
func HasPool() predicate.UpstreamAccount {
	return predicate.UpstreamAccount(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, PoolTable, PoolColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasPoolWith applies the HasEdge predicate on the "pool" edge with a given conditions (other predicates).
func HasPoolWith(preds ...predicate.UpstreamAccountPool) predicate.UpstreamAccount {
	return predicate.UpstreamAccount(func(s *sql.Selector) {
		step := newPoolStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.UpstreamAccount) predicate.UpstreamAccount {
	return predicate.UpstreamAccount(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.UpstreamAccount) predicate.UpstreamAccount {
	return predicate.UpstreamAccount(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.UpstreamAccount) predicate.UpstreamAccount {
	return predicate.UpstreamAccount(sql.NotPredicates(p))
}
